window.RP_SESSION={"id":"S-9c3cf237ae44","messages":[{"id":"RP-II-0059045","time":"2026-03-09T20:34:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"브라그니르 라르손은 두꺼운 삼중장갑과 보안경, 상아로만든 가면, 그리고 소매까지덮는 두꺼운 가죽옷과 바지까지입고 물약 공방에서 작은 냄비에 뭔가를 끓이고있다.\n\n\"시체눈깔버섯, 복어간...\"\n\n쓴맛을 숨기기위해 맥아와 밀을 조금넣어서 끓이고있는 용액에 시체눈깔버섯을 먼저 투하한다. 이후 불을 조금 낮추고 복어간을, 그리고 온도를 조금씩 낮추면서 갖가지 버섯, 식물, 동물에서 유래된 독을 집어넣고, 마지막에 짐새의 깃털과 피마자 씨앗을 넣어 물약을 완성한다. 불이 꺼지고도 잠시의 시간이 지날때까지 기다리고는.\n\n\"라르손 특제 저승포션 완성일세!\"\n\n라르손은 조심조심 일회용국자와 깔대기로 저승포션을 백랍제 병에 담은다음, 냄비, 국자, 깔대기를 한데 놓고 위에 해골표시를 한뒤 내다버린다!\n\n\"누가 주워다쓰진 않겠지?\"","characters":["P-b551ad21c43a"]},{"id":"RP-II-0059046","time":"2026-03-09T20:34:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"재탕.","characters":["P-b551ad21c43a"]},{"id":"RP-II-0059047","time":"2026-03-09T20:34:00+09:00","room":"RP II","name":"브라그니르 라르손","profile":"브라그니르 라르손","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b551ad21c43a"]},{"id":"RP-II-0059048","time":"2026-03-09T20:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
